// Node tolerant parse
const findJson = (s) => {
  const m = s.match(/\{[\s\S]*\}$/);
  return m ? JSON.parse(m[0]) : null;
}
try {
  const payload = findJson(responseText);
  // run ajv validate(payload, schema)
} catch (e) { /* fallback */ }
```

